<?php require __DIR__.'/../lib/bootstrap.php';require_admin();$pageTitle='Pedidos';$status=trim($_GET['status']??'');$eventId=(int)($_GET['event']??0);$q=trim($_GET['q']??'');release_expired_orders();
$events=db()->query('SELECT id,title,event_date FROM events ORDER BY datetime(event_date) DESC')->fetchAll();$sql='SELECT o.*,e.title event_title,e.event_date FROM orders o JOIN events e ON e.id=o.event_id WHERE 1=1';$args=[];
if(in_array($status,['pending','paid','review','cancelled','refunded','expired'],true)){$sql.=' AND o.status=?';$args[]=$status;}if($eventId){$sql.=' AND o.event_id=?';$args[]=$eventId;}if($q!==''){$sql.=' AND (o.order_number LIKE ? OR o.buyer_name LIKE ? OR o.buyer_email LIKE ? OR o.buyer_document LIKE ?)';for($i=0;$i<4;$i++)$args[]='%'.$q.'%';}$sql.=' ORDER BY o.id DESC';$st=db()->prepare($sql);$st->execute($args);$orders=$st->fetchAll();$sum=array_sum(array_map(fn($o)=>$o['status']==='paid'?(float)$o['total']:0,$orders));require '_header.php';?>
<div class="metric-grid compact-metrics"><div class="metric"><span>Pedidos exibidos</span><strong><?=count($orders)?></strong></div><div class="metric"><span>Receita paga exibida</span><strong><?=money($sum)?></strong></div></div><div class="admin-card"><div class="card-head"><div><h2>Vendas de ingressos</h2><p>Acompanhe reservas, pagamentos e emissão dos ingressos digitais.</p></div><a class="btn btn-small btn-secondary" href="export.php?type=orders<?= $eventId?'&event='.$eventId:'' ?>">Exportar CSV</a></div><form class="filters" method="get"><select name="event"><option value="0">Todos os eventos</option><?php foreach($events as $ev):?><option value="<?=intval($ev['id'])?>" <?=$eventId===(int)$ev['id']?'selected':''?>><?=e($ev['title'])?> — <?=date_br($ev['event_date'])?></option><?php endforeach;?></select><select name="status"><option value="">Todos os status</option><?php foreach(['pending'=>'Pendente','paid'=>'Pago','review'=>'Em revisão','cancelled'=>'Cancelado','refunded'=>'Reembolsado','expired'=>'Expirado'] as $v=>$l):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select><input name="q" value="<?=e($q)?>" placeholder="Pedido, nome, e-mail ou documento"><button class="btn btn-small btn-secondary">Filtrar</button></form><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Comprador</th><th>Evento</th><th>Total</th><th>Status</th><th>Data</th><th></th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="7">Nenhum pedido encontrado.</td></tr><?php endif;?><?php foreach($orders as $o):?><tr><td><b><?=e($o['order_number'])?></b></td><td><?=e($o['buyer_name'])?><small class="cell-sub"><?=e($o['buyer_email'])?></small></td><td><?=e($o['event_title'])?></td><td><b><?=money((float)$o['total'])?></b></td><td><span class="pill <?=e($o['status'])?>"><?=e(status_label($o['status']))?></span></td><td><?=e(dt_db_br($o['created_at']))?></td><td><a href="order.php?id=<?=intval($o['id'])?>">Abrir</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require '_footer.php';?>
